# ======================================================================================================== 3: the egg item flavor text
P.rep('''import tier_tags as _TT     # the standing tier-tag rule: "Rare Egg - ..." comes from the one table
''', '''import tier_tags as _TT     # the standing tier-tag rule: "Rare Egg - ..." comes from the one table
# 0.4.21 (the rarity + tooltip pass, Style Guide 15): the egg flavor texts in lang <color is=...> spans (the vanilla server.lang markup) -
# the tier tag in the egg's rarity colour, a line break (lang \\n), the sentence soft white, the craft / trade note dim, the rarity words in
# their own colours. _LPLAIN(text) = the text with the spans stripped and the line break put back to the tag's " - ".
_LRC = dict(zip(RARITIES, RARITY_COLORS))
_LSOFT, _LDIM = "#d6e4ee", "#7f93a6"
_LSPAN = re.compile(r"</?color[^>]*>")


def _LC(col, text):
    return '<color is="%s">%s</color>' % (col, text) if text else ""


def _LRTM(col, text):
    """text in colour col, every "Rare to Mythic" with Rare / Mythic in their own rarity colours"""
    out, rest = [], text
    while "Rare to Mythic" in rest:
        a, rest = rest.split("Rare to Mythic", 1)
        out += [_LC(col, a), _LC(_LRC["Rare"], "Rare"), _LC(col, " to "), _LC(_LRC["Mythic"], "Mythic")]
    return "".join(out) + _LC(col, rest)


def _LPLAIN(x):
    return _LSPAN.sub("", x).replace("\\\\n", _TT.SEP, 1)


def _LFLAV(item_id, plain, rar, dim_from):
    """the coloured lang text of one egg: plain = the 0.4.20 text ("<tag> - <sentence><dim note>"), dim_from = where the dim note starts"""
    tag = _TT.tag_for(item_id)
    assert plain.startswith(tag + _TT.SEP) and dim_from > len(tag + _TT.SEP), (item_id, plain)
    out = _LC(_LRC[rar], tag) + "\\\\n" + _LRTM(_LSOFT, plain[len(tag + _TT.SEP):dim_from]) + _LC(_LDIM, plain[dim_from:])
    assert _LPLAIN(out) == plain and "\\n" not in out, "0.4.21: the coloured text keeps every word: %s" % item_id
    assert _LSPAN.sub("", out).startswith(tag + "\\\\n"), "0.4.21: the tier tag first (span-stripped): %s" % item_id
    return out
''')
P.rep('''        assert _d.startswith(_TT.tag_for(_eid) + _TT.SEP) and _TT.owner(_eid) is None and _eid in _TT.rarity_ids_for("SkyyPets"), "0.4.0: the tier tag (tools/tier_tags.py) first: %s" % _eid
        _elang += ["items.%s.name=%s" % (_eid, EGG.name(_c, _r)), "server.items.%s.name=%s" % (_eid, EGG.name(_c, _r)),
                   "items.%s.description=%s" % (_eid, _d), "server.items.%s.description=%s" % (_eid, _d)]
''', '''        assert _d.startswith(_TT.tag_for(_eid) + _TT.SEP) and _TT.owner(_eid) is None and _eid in _TT.rarity_ids_for("SkyyPets"), "0.4.0: the tier tag (tools/tier_tags.py) first: %s" % _eid
        _dn = " Craft it in /pets > Eggs." if _in is not None else " Trade it"          # 0.4.21: the dim note = the craft / trade sentences
        _d = _LFLAV(_eid, _d, _r, _d.index(_dn))
        _elang += ["items.%s.name=%s" % (_eid, EGG.name(_c, _r)), "server.items.%s.name=%s" % (_eid, EGG.name(_c, _r)),
                   "items.%s.description=%s" % (_eid, _d), "server.items.%s.description=%s" % (_eid, _d)]
''')
P.rep('''        assert _dd.startswith("Legendary Egg" + _TT.SEP) and _e[0] in _TT.rarity_ids_for("SkyyPets", "secretegg") and "ragon" not in _dd and len(_dd) < 300, _e[0]
''', '''        assert _dd.startswith("Legendary Egg" + _TT.SEP) and _e[0] in _TT.rarity_ids_for("SkyyPets", "secretegg") and "ragon" not in _dd and len(_dd) < 300, _e[0]
        _dd = _LFLAV(_e[0], _dd, "Legendary", _dd.index(" The egg can"))          # 0.4.21: coloured (the plain text asserted above)
        assert "ragon" not in _LPLAIN(_dd) and len(_LPLAIN(_dd)) < 300, _e[0]
''')
P.rep('''        assert _dd.startswith("Legendary Dragon Egg" + _TT.SEP) and _e[0] in _TT.rarity_ids_for("SkyyPets", "dragonegg") and len(_dd) < 300, _e[0]
''', '''        assert _dd.startswith("Legendary Dragon Egg" + _TT.SEP) and _e[0] in _TT.rarity_ids_for("SkyyPets", "dragonegg") and len(_dd) < 300, _e[0]
        _dd = _LFLAV(_e[0], _dd, "Legendary", _dd.index(" The egg can"))          # 0.4.21: coloured (the plain text asserted above)
        assert len(_LPLAIN(_dd)) < 300, _e[0]
''')

assert P.s.count("registerCommand(") == REG0 and P.s.count("registerSystem(") == SYS0 and P.s.count("= cls(") == CLS0, "0.4.21 adds no class, system or command"
