for _dep in ("public static int eggRar(String id)", "public static String tcol(String hex, String t)", "public static String typeLine(String kind, int lv)",
             "public static String fuseInfo(", "public static String eggText(String egg)",
             "public static int[] weights()", "public static int[] eggRarity(int r)", "public static String rarityName("):
    assert _i(_dep) < _i("public static String eggCol(String id)"), "0.4.21: methods before callers: " + _dep
assert _i("public static String rcolOf(int r) { return r >= 1 && r <= RCOL.length ? RCOL[r - 1] : RCOL[0]; }") < _i("public static String oddsCol(") < _i("public static @IGS@ eggCell(")
assert P.s.index("public static String pct(double d) {\n  if (!(d > 0.0))") < _i("public static String oddsCol(")
assert _i("public static String tsec(") < _i("public static @IGS@ eggCell(") < _i("public static @IGS@ petCell(")
assert _i("public static String nameCol(") < _i("BUILD_H = r") and _i("public static String nameCol(") > _i("public static String rcolOf(int r) { return r >= 1 && r <= RCOL.length ? RCOL[r - 1] : \\\"")
P.finish()
